import React, { useState, useMemo } from "react"
import { graphql } from "gatsby"
import _ from "lodash"

import Layout from "components/Layout"
import SEO from "components/SEO"
import PostList from "components/PostList"
import VerticalSpace from "components/VerticalSpace"
import TextField from "components/TextField"

const SearchPage = ({ data }) => {
  const posts = data.allMarkdownRemark.nodes
  const [query, setQuery] = useState("")

  const filteredPosts = useMemo(() => {
    if (!query) return posts

    const queryLower = query.toLowerCase()
    return posts.filter(post => {
      const { title, tags } = post.frontmatter
      const { excerpt } = post
      
      // 제목에서 검색
      if (title && title.toLowerCase().includes(queryLower)) {
        return true
      }
      
      // 태그에서 검색
      if (tags && tags.some(tag => tag.toLowerCase().includes(queryLower))) {
        return true
      }
      
      // 내용에서 검색
      if (excerpt && excerpt.toLowerCase().includes(queryLower)) {
        return true
      }
      
      // 본문에서 검색
      if (post.rawMarkdownBody && post.rawMarkdownBody.toLowerCase().includes(queryLower)) {
        return true
      }
      
      return false
    })
  }, [posts, query])

  return (
    <Layout>
      <SEO title="Search" />
      <VerticalSpace size={48} />
      <TextField
        placeholder="검색어를 입력하세요"
        onChange={setQuery}
        value={query}
      />
      <VerticalSpace size={24} />
      <PostList postList={filteredPosts} />
    </Layout>
  )
}

export default SearchPage

export const pageQuery = graphql`
  query {
    allMarkdownRemark(
      sort: { frontmatter: { date: DESC } }
      filter: { fileAbsolutePath: { regex: "/contents/posts/" } }
    ) {
      nodes {
        excerpt(pruneLength: 200, truncate: true)
        html
        fields {
          slug
          readingTime {
            minutes
          }
        }
        frontmatter {
          date
          title
          tags
        }
        rawMarkdownBody
      }
    }
  }
`
