const POSTS_PER_PAGE = 10

// HTML에서 이미지 URL 추출 함수 (개선된 버전)
const extractFirstImage = (html) => {
  if (!html) {
    return null
  }
  
  // 1순위: gif 파일 찾기 (애니메이션 우선)
  const gifPatterns = [
    /<img[^>]+src="([^">]*\.gif[^">]*)"[^>]*>/i,
    /<img[^>]+data-main-image[^>]+src="([^">]*\.gif[^">]*)"[^>]*>/i,
    /<picture[^>]*>[\s\S]*?<img[^>]+src="([^">]*\.gif[^">]*)"[\s\S]*?<\/picture>/i,
    /<source[^>]+srcset="([^">]*\.gif[^">]*)"[^>]*>/i,
  ]
  
  for (const pattern of gifPatterns) {
    const match = html.match(pattern)
    if (match && match[1]) {
      const imageSrc = processImageSrc(match[1])
      if (imageSrc) {
        return imageSrc
      }
    }
  }
  
  // 2순위: 다른 이미지 파일들 (png, jpg, jpeg, webp 등)
  const imagePatterns = [
    // Gatsby v5 Sharp 이미지들
    /<img[^>]+data-gatsby-image-ssr[^>]+src="([^">]+)"[^>]*>/i,
    /<img[^>]+data-main-image[^>]+src="([^">]+)"[^>]*>/i,
    /<img[^>]+class="[^"]*gatsby-resp-image[^"]*"[^>]+src="([^">]+)"[^>]*>/i,
    
    // srcset에서 가장 큰 이미지 추출
    /<img[^>]+srcset="([^">]+)"[^>]*>/i,
    
    // 일반 img 태그들
    /<img[^>]+src="([^">]+\.(png|jpe?g|webp|avif|svg))"[^>]*>/i,
    /<img[^>]+src="([^">]+)"[^>]*>/i,
    
    // picture 태그 내의 source와 img
    /<picture[^>]*>[\s\S]*?<source[^>]+srcset="([^">]+)"[\s\S]*?<\/picture>/i,
    /<picture[^>]*>[\s\S]*?<img[^>]+src="([^">]+)"[\s\S]*?<\/picture>/i,
    
    // Gatsby StaticImage 컴포넌트
    /<div[^>]+class="[^"]*gatsby-image-wrapper[^"]*"[^>]*>[\s\S]*?<img[^>]+src="([^">]+)"/i,
    
    // 일반적인 이미지 패턴들
    /<figure[^>]*>[\s\S]*?<img[^>]+src="([^">]+)"[\s\S]*?<\/figure>/i,
    /<a[^>]*>[\s\S]*?<img[^>]+src="([^">]+)"[\s\S]*?<\/a>/i,
  ]
  
  for (let i = 0; i < imagePatterns.length; i++) {
    const pattern = imagePatterns[i]
    const match = html.match(pattern)
    
    if (match && match[1]) {
      let imageSrc = match[1]
      
      // srcset의 경우 가장 큰 이미지 선택
      if (imageSrc.includes(',')) {
        const srcsetItems = imageSrc.split(',').map(item => item.trim())
        // 가장 큰 해상도의 이미지 선택 (마지막 항목이 보통 가장 큼)
        const bestSrc = srcsetItems[srcsetItems.length - 1].split(' ')[0]
        imageSrc = bestSrc
      }
      
      const processedSrc = processImageSrc(imageSrc)
      if (processedSrc) {
        return processedSrc
      }
    }
  }
  
  return null
}

// 이미지 src 처리 함수 (개선된 버전)
const processImageSrc = (src) => {
  if (!src) return null
  
  let imageSrc = src.trim()
  
  // 빈 문자열이나 너무 짧은 URL 제외
  if (imageSrc.length <= 3) {
    return null
  }
  
  // data URI나 플레이스홀더 제외
  if (imageSrc.startsWith('data:') || 
      imageSrc.includes('placeholder') || 
      imageSrc.includes('loading') ||
      imageSrc.includes('blur-up') ||
      imageSrc.includes('traced')) {
    return null
  }
  
  // URL 디코딩
  try {
    imageSrc = decodeURIComponent(imageSrc)
  } catch (e) {
    // 디코딩 실패시 원본 사용
  }
  
  // 상대 경로를 절대 경로로 변환
  if (imageSrc.startsWith('./') || imageSrc.startsWith('../')) {
    imageSrc = imageSrc.replace(/^\.\.?\//, '/')
  }
  
  // Gatsby static 경로 처리
  if (!imageSrc.startsWith('http') && !imageSrc.startsWith('/') && !imageSrc.startsWith('//')) {
    imageSrc = '/' + imageSrc
  }
  
  // 프로토콜 상대 URL 처리
  if (imageSrc.startsWith('//')) {
    imageSrc = 'https:' + imageSrc
  }
  
  // 유효한 이미지 확장자인지 확인
  const imageExtensions = ['.png', '.jpg', '.jpeg', '.gif', '.webp', '.avif', '.svg']
  const hasValidExtension = imageExtensions.some(ext => 
    imageSrc.toLowerCase().includes(ext)
  )
  
  // 확장자가 없지만 Gatsby 처리된 이미지일 수 있음 (쿼리 파라미터 포함)
  const isGatsbyImage = imageSrc.includes('static/') || 
                        imageSrc.includes('images/') ||
                        imageSrc.includes('?') ||
                        imageSrc.includes('#')
  
  if (!hasValidExtension && !isGatsbyImage) {
    return null
  }
  
  return imageSrc
}

const PostList = ({ postList }) => {
  const [currentPage, setCurrentPage] = useState(1)
  
  const totalPages = Math.ceil(postList.length / POSTS_PER_PAGE)
  const startIndex = (currentPage - 1) * POSTS_PER_PAGE
  const endIndex = startIndex + POSTS_PER_PAGE
  const currentPosts = postList.slice(startIndex, endIndex)

  const handlePageChange = (page) => {
    setCurrentPage(page)
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }

  const handlePrevPage = () => {
    if (currentPage > 1) {
      handlePageChange(currentPage - 1)
    }
  }

  const handleNextPage = () => {
    if (currentPage < totalPages) {
      handlePageChange(currentPage + 1)
    }
  }

  // 페이지 번호 배열 생성 (최대 5개 페이지 표시)
  const getPageNumbers = () => {
    const pages = []
    const maxVisiblePages = 5
    
    if (totalPages <= maxVisiblePages) {
      for (let i = 1; i <= totalPages; i++) {
        pages.push(i)
      }
    } else {
      if (currentPage <= 3) {
        for (let i = 1; i <= 5; i++) {
          pages.push(i)
        }
      } else if (currentPage >= totalPages - 2) {
        for (let i = totalPages - 4; i <= totalPages; i++) {
          pages.push(i)
        }
      } else {
        for (let i = currentPage - 2; i <= currentPage + 2; i++) {
          pages.push(i)
        }
      }
    }
    
    return pages
  }

  useEffect(() => {
    setCurrentPage(1)
  }, [postList])

  return (
    <>
      <PostCount>
        총 <strong>{postList.length}</strong>개의 포스트 중 <strong>{startIndex + 1}-{Math.min(endIndex, postList.length)}</strong>번째 포스트
      </PostCount>
      
      <PostListWrapper>
        {currentPosts.map((post, i) => {
          const { title, date, tags, thumbnail } = post.frontmatter
          const { excerpt } = post
          const { slug, readingTime } = post.fields
          
          // 1순위: frontmatter의 thumbnail 사용 (File 객체의 publicURL)
          // 2순위: HTML에서 첫 번째 이미지 추출 (gif 우선순위)
          const firstImage = thumbnail?.publicURL || extractFirstImage(post.html)
          
          // 읽기 시간 계산 (기존 포스트 페이지와 동일한 방식)
          const readingTimeText = readingTime ? `${Math.round(readingTime.minutes)}분 읽기` : '1분 읽기'

          return (
            <PostWrapper key={JSON.stringify({ slug, date })}>
              <PostLink to={slug}>
                <PostContent>
                  <PostMainContent>
                    <PostTextContent hasImage={!!firstImage}>
                      <div>
                        <PostHeader>
                          <PostTitle>{title}</PostTitle>
                          <PostMeta>
                            <RelativeDate>{getRelativeTime(date)}</RelativeDate>
                            <ReadingTime>{readingTimeText}</ReadingTime>
                          </PostMeta>
                        </PostHeader>
                        
                        <Excerpt hasImage={!!firstImage}>{excerpt}</Excerpt>
                      </div>
                      
                      {!firstImage && (
                        <PostFooter>
                          <TagList tagList={tags} />
                        </PostFooter>
                      )}
                    </PostTextContent>
                  </PostMainContent>
                  
                  {firstImage && (
                    <PostImageWrapper data-image-wrapper>
                      <PostImage 
                        src={firstImage} 
                        alt={title} 
                        loading="lazy" 
                        onError={(e) => {
                          // 이미지 로딩 실패시 부모 wrapper 숨김
                          const wrapper = e.target.closest('[data-image-wrapper]')
                          if (wrapper) {
                            wrapper.style.display = 'none'
                          }
                          
                          // 디버깅 정보 출력 (개발 환경에서만)
                          if (process.env.NODE_ENV === 'development') {
                            console.warn('📸 이미지 로딩 실패:', {
                              src: firstImage,
                              title: title,
                              naturalSrc: e.target.src,
                              error: e.target.error || 'Unknown error'
                            })
                          }
                        }}
                        onLoad={(e) => {
                          // 이미지 로딩 성공시 디버깅 정보 (개발 환경에서만)
                          if (process.env.NODE_ENV === 'development') {
                            console.log('✅ 이미지 로딩 성공:', {
                              src: firstImage,
                              title: title,
                              naturalWidth: e.target.naturalWidth,
                              naturalHeight: e.target.naturalHeight
                            })
                          }
                        }}
                      />
                    </PostImageWrapper>
                  )}
                </PostContent>
                
                {firstImage && (
                  <PostFullWidthFooter>
                    <TagList tagList={tags} />
                  </PostFullWidthFooter>
                )}
              </PostLink>
            </PostWrapper>
          )
        })}
      </PostListWrapper>
      
      {totalPages > 1 && (
        <PaginationWrapper>
          <PaginationButton 
            onClick={handlePrevPage}
            disabled={currentPage === 1}
          >
            <FaChevronLeft />
          </PaginationButton>
          
          {getPageNumbers().map(page => (
            <PaginationButton
              key={page}
              active={page === currentPage}
              onClick={() => handlePageChange(page)}
            >
              {page}
            </PaginationButton>
          ))}
          
          <PaginationButton 
            onClick={handleNextPage}
            disabled={currentPage === totalPages}
          >
            <FaChevronRight />
          </PaginationButton>
          
          <PageInfo>
            {currentPage} / {totalPages} 페이지
          </PageInfo>
        </PaginationWrapper>
      )}
    </>
  )
}

export default PostList
